    /**
     * assign Workspace on FeatureSet
     * @param		command AssignWorkspaceToFeatureSetCommand	
     * @exception	ProcessingException
     */     
	public void assignWorkspace( AssignWorkspaceToFeatureSetCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	FeatureSetValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignWorkspace(command.getFeatureSetId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AnalyticsWorkspace using id " + command.getFeatureSetId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

